<?php defined('ABSPATH')||exit;$count=WC()->cart->get_cart_contents_count();?>
<div class="juhani-order-drawer-content jdp-shell"><header class="jdp-header"><div><span class="jdp-eyebrow">READY FOR YOUR NEXT CATCH</span><div class="jdp-title-row"><h2 id="juhani-order-drawer-title" tabindex="-1">Your cart</h2><span class="jdp-count"><?php echo esc_html($count);?> <?php echo $count===1?'item':'items';?></span></div><p>Good gear, almost yours.</p></div><button type="button" class="jdp-close" data-close-order-drawer aria-label="Close cart drawer"><?php echo juhani_order_svg('close');?></button></header>
<div class="jdp-scroll"><div class="jdp-items">
<?php foreach(WC()->cart->get_cart() as $key=>$item):$product=apply_filters('woocommerce_cart_item_product',$item['data'],$item,$key);if(!$product||!$product->exists()||$item['quantity']<=0||!apply_filters('woocommerce_widget_cart_item_visible',true,$item,$key))continue;$name=apply_filters('woocommerce_cart_item_name',$product->get_name(),$item,$key);$url=apply_filters('woocommerce_cart_item_permalink',$product->is_visible()?$product->get_permalink($item):'',$item,$key);?>
<article class="jdp-item"><a class="jdp-photo" href="<?php echo esc_url($url);?>"><?php echo apply_filters('woocommerce_cart_item_thumbnail',$product->get_image('woocommerce_thumbnail'),$item,$key);?></a><div><div class="jdp-item-top"><div><span class="jdp-category">CAST NET / FISHING GEAR</span><h3><a href="<?php echo esc_url($url);?>"><?php echo wp_kses_post($name);?></a></h3></div><button type="button" class="jdp-remove" data-order-remove="<?php echo esc_attr($key);?>" aria-label="<?php echo esc_attr('Remove '.wp_strip_all_tags($name));?>"><?php echo juhani_order_svg('remove');?></button></div><?php juhani_order_spec_chips($item,'jdp-specs');?><div class="jdp-item-bottom"><div class="jdp-quantity"><button type="button" data-order-step="-1" data-cart-key="<?php echo esc_attr($key);?>" data-quantity="<?php echo esc_attr($item['quantity']);?>" aria-label="Decrease quantity">−</button><input type="number" data-order-quantity="<?php echo esc_attr($key);?>" min="1" max="<?php echo esc_attr($product->is_sold_individually()?1:($product->get_max_purchase_quantity()>0?$product->get_max_purchase_quantity():''));?>" value="<?php echo esc_attr($item['quantity']);?>" aria-label="Quantity"><button type="button" data-order-step="1" data-cart-key="<?php echo esc_attr($key);?>" data-quantity="<?php echo esc_attr($item['quantity']);?>" aria-label="Increase quantity">+</button></div><div class="jdp-price"><strong><?php echo WC()->cart->get_product_subtotal($product,$item['quantity']);?></strong><small><?php echo WC()->cart->get_product_price($product);?> each</small></div></div></div></article>
<?php endforeach;if(!$count):?><div class="jdp-empty"><?php echo juhani_order_svg('bag');?><h3>Your next catch awaits.</h3><p>Your cart is empty.<br>Find the right gear for your next trip.</p><a class="jdp-browse" href="<?php echo esc_url(juhani_order_shop_url());?>">Explore our collection →</a></div><?php endif;?></div>
<div class="jdp-help-note"><span class="jdp-help-symbol">?</span><div><strong>The right net makes a difference.</strong><p>Need a hand with sizes or materials?</p><a href="tel:+8801889164315">Talk to Juhani ↗</a></div></div></div>
<footer class="jdp-footer"><div class="jdp-subtotal"><span>Subtotal</span><strong><?php echo WC()->cart->get_cart_subtotal();?></strong></div><p class="jdp-delivery-note">Delivery is calculated at checkout.</p><a class="jdp-checkout" href="<?php echo esc_url(wc_get_checkout_url());?>" <?php if(!$count)echo 'aria-disabled="true" tabindex="-1"';?>><span>Continue to checkout</span><?php echo juhani_order_svg();?></a><a class="jdp-view-cart" href="<?php echo esc_url(wc_get_cart_url());?>">View full cart ↗</a><div class="jdp-cod-note"><?php echo juhani_order_svg('check');?> Cash on delivery available</div></footer></div>
